ly:Consolas,'Courier New',monospace;color:#c9bfd8;font-size:10px;line-height:1.75;overflow:auto;padding:17px 16px;margin:0;min-height:190px;tab-size:2}.skill-detail-content{animation:skill-change .35s ease-out}.skill-detail-bottom{display:flex;align-items:center;gap:8px;font-size:7px;color:#81848e;margin-top:18px}.skill-detail-bottom :global(svg){color:var(--skill-color)}.skill-copy-status{font-size:8px;color:#bfc3b5;min-height:12px;margin-top:10px}.skill-card:focus-visible,.skill-filter button:focus-visible{outline-color:#8d6daf}.skill-editor button:focus-visible{outline-color:#bda1ed}
