  @media(max-width:1050px){.skill-layout{grid-template-columns:1fr 1fr;gap:20px}.skill-grid{grid-template-columns:repeat(3,1fr);gap:10px}.skill-card{padding:17px 13px;min-height:140px}.skill-card-top{margin-bottom:17px}.skill-card strong{font-size:12px}.skill-detail{padding:23px}.skills-heading>p{font-size:10px}.skill-detail-name h3{font-size:28px}}
  @media(max-width:760px){.skills-section{padding-block:30px 45px}.skills-heading{display:block;margin-bottom:23px}.skills-heading h2{font-size:42px}.skills-heading>p{margin-top:18px;font-size:10px}.skill-layout{grid-template-columns:1fr;gap:20px}.skill-grid{grid-template-columns:repeat(4,1fr)}.skill-card{padding:18px 15px;min-height:140px}.skill-detail{padding:25px}.skill-description{min-height:0;max-width:470px}.skill-editor pre{min-height:170px}.skill-detail-top{font-size:7px}.skill-filter{padding-bottom:18px;margin-bottom:20px}.skill-filter button{padding:9px 14px}}
